using System;using System.Linq;using UnityEngine;using OneWay.Battle3D;
public static class TestB2Slash {
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);}
 public static object Run(){Check(Application.isPlaying,"Play required");var source=UnityEngine.Object.FindObjectsByType<B2SwordSlash>(FindObjectsInactive.Include,FindObjectsSortMode.None).First();var g=UnityEngine.Object.Instantiate(source.boss.gameObject);g.name="Temporary B2 slash test";g.transform.position=new Vector3(1000,0,1000);g.SetActive(true);var emitter=g.GetComponentInChildren<B2SwordSlash>(true);var boss=emitter.boss;var a=emitter.GetComponent<Animator>();var before=UnityEngine.Object.FindObjectsByType<B2SlashFlight>(FindObjectsSortMode.None).ToArray();try{foreach(var b in g.GetComponentsInChildren<MonoBehaviour>(true))if(b!=emitter)b.enabled=false;emitter.gameObject.SetActive(true);boss.ResetBoss();a.cullingMode=AnimatorCullingMode.AlwaysAnimate;a.Rebind();a.Play("Base Layer.HeavyHammerLoop",0,0);a.Update(0);int count=emitter.EmittedCount;for(int i=0;i<43;i++)a.Update(1f/30);Check(emitter.EmittedCount==count,"Emitted during preparation");a.Update(2f/30);Check(emitter.EmittedCount==count+1,"Downswing did not emit");for(int i=0;i<108;i++)a.Update(1f/30);Check(emitter.EmittedCount==count+3,"Not once per loop");var shots=UnityEngine.Object.FindObjectsByType<B2SlashFlight>(FindObjectsSortMode.None).Except(before).ToArray();Check(shots.Length==3,"Wrong projectile count");foreach(var s in shots){float height=s.GetComponent<Renderer>().bounds.size.y;Check(Mathf.Abs(height-emitter.BossHeight*2)<.01f,"Wrong height "+height);Check(s.GetComponent<Renderer>().sharedMaterial.shader.name=="Universal Render Pipeline/Unlit","Wrong white shader");var start=s.transform.position;s.SendMessage("Update");Check(Vector3.Dot(s.transform.position-start,boss.transform.forward)>=0,"Travels backwards");}
 float original=emitter.BossHeight;g.transform.localScale*=2;emitter.EmitB2SwordSlash();Check(Mathf.Abs(emitter.BossHeight-original*2)<.01f,"Size does not follow boss scale");return new{passed=true,threeLoopsThreeSlashes=true,fireFrame=44,bossHeight=original,slashHeight=original*2,scaleResponsive=true};
 }finally{UnityEngine.Object.DestroyImmediate(g);foreach(var shot in UnityEngine.Object.FindObjectsByType<B2SlashFlight>(FindObjectsSortMode.None).Except(before))UnityEngine.Object.DestroyImmediate(shot.gameObject);}}
}
